uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// User Parameters (Preserved)
uniform float u_speed;
uniform float u_fov;
uniform float u_camera_dist;
uniform float u_glow_intensity;
uniform float u_complexity; 
uniform float u_viscosity;
uniform float u_paper_texture;
uniform float u_metallic_shine;
uniform float u_bloom_brightness;
uniform float u_paint_thickness;
uniform float u_creaminess;
uniform float u_melting;
uniform float u_berry_intensity; 
uniform float u_wave_height;

// New Parameters for the Central Hole
uniform float u_hole_size;
uniform float u_vortex_strength;

// Updated for Lush Orange theme
uniform float u_orange_hue;

out vec4 fragColor;

// --- UTILS ---
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float noise(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Multi-tone Palette updated for "Lush Orange"
// Swapping Blues for Deep Amber, Blood Orange, and Peach Cream
vec3 getIceCreamPalette(float t, float mask) {
    // Deep, dark burnt orange for shadows
    vec3 deepAmber    = vec3(0.25, 0.08, 0.02) * u_berry_intensity; 
    // Vibrant primary orange
    vec3 lushOrange   = vec3(1.0, 0.45, 0.0) * u_berry_intensity; 
    // Soft creamy peach
    vec3 peachCream   = vec3(1.0, 0.92, 0.8); 

    // Inject a bit of blood-orange/red richness
    vec3 redDepth     = vec3(0.5, 0.05, 0.0);

    float selector = sin(t * 1.5 + mask * 4.0) * 0.5 + 0.5;

    vec3 finalCol = mix(deepAmber, lushOrange, smoothstep(0.1, 0.7, selector));
    finalCol = mix(finalCol, peachCream, smoothstep(0.75, 0.98, selector) * u_creaminess);

    // Inject extra lushness based on the orange shift parameter (u_orange_hue replacing blue_shift)
    finalCol = mix(finalCol, redDepth, (1.0 - selector) * u_orange_hue * 0.6);

    return finalCol;
}

void main() {
    // 1. Coordinate Setup
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv_orig = uv;

    // Zoom control
    uv *= (3.0 - u_fov); 

    float t = iTime * u_speed * 0.15;
    float r = length(uv);
    float angle = atan(uv.y, uv.x);

    // 2. Liquid Distortion & Vortex Folding
    float vortex = u_vortex_strength / (r + 0.1);
    uv *= rot(vortex + t * 0.5);

    // Suck the UVs into the hole (Inverse distance)
    float pull = pow(clamp(1.0 - r, 0.0, 1.0), 2.0) * 0.5;
    vec2 p = uv * (1.0 + pull);

    float flow = 0.0;

    // Melt effect: Slight downward drag + radial inward flow
    p.y -= t * u_melting * 0.25;

    // Wave influence for fractal folding
    float waveAmp = u_wave_height;

    for(float i = 1.0; i <= u_complexity; i++) {
        p.x += (waveAmp / i) * sin(i * 1.8 * p.y + t + u_viscosity * 4.0);
        p.y += (waveAmp / i) * cos(i * 1.8 * p.x + t + u_viscosity * 4.0);

        p *= rot(u_camera_dist * 0.04);

        flow += length(p - uv);
    }

    // 3. Distance Fields for the Creamy folds + Center Hole
    float d = length(sin(p * 0.9)) - 0.45;

    // Create the hole mask
    float hole = smoothstep(u_hole_size, u_hole_size + 0.1, r);
    // Darken internal depth as it approaches hole
    float holeDepth = smoothstep(u_hole_size - 0.1, u_hole_size + 0.5, r);

    // Soft blend for "Thick" feel
    float mask = smoothstep(1.0 + u_paint_thickness * 0.5, -0.3, d) * hole;

    // Add internal depth glow
    float glow = exp(-abs(d) * 4.0) * u_glow_intensity * hole;

    // 4. Color Compositing
    vec3 baseCol = getIceCreamPalette(flow * 0.12 + t * 0.15, mask);
    baseCol *= holeDepth; // Darken towards the hole

    // Background (Pit depth) - Deep volcanic obsidian black/brown
    vec3 bgCol = vec3(0.04, 0.01, 0.0); 
    vec3 finalCol = mix(bgCol, baseCol, clamp(mask + glow, 0.0, 1.0));

    // 5. Glossy Reflections
    vec3 n = normalize(vec3(dFdx(flow), dFdy(flow), 0.2 / (0.1 + u_wave_height))); 
    vec3 lightDir = normalize(vec3(sin(t * 0.3), 1.0, 1.5));
    float spec = pow(max(0.0, dot(n, lightDir)), 12.0) * u_metallic_shine * hole;

    // Highlights are now warm golden white
    vec3 highlight = mix(baseCol, vec3(1.0, 0.98, 0.85), 0.7);
    finalCol += spec * highlight * u_bloom_brightness;

    // 6. Surface Texture (Orange Zest/Seeds)
    float grain = noise(gl_FragCoord.xy * 0.4);
    if (u_paper_texture > 0.0) {
        float seedPattern = step(0.98, noise(p * 15.0 + flow));
        // Seeds are now dark brownish-red (zest)
        finalCol = mix(finalCol, vec3(0.15, 0.02, 0.0), seedPattern * u_paper_texture * 3.0 * hole);
        finalCol *= 1.0 - (grain * u_paper_texture * 0.5);
    }

    // 7. Post Processing
    float vignette = smoothstep(1.3, 0.4, length(uv_orig));
    finalCol *= vignette;

    // Final Toning - Contrast boost for "Lush" feel
    finalCol = pow(finalCol, vec3(0.9)); 
    finalCol = smoothstep(-0.02, 1.02, finalCol);

    fragColor = vec4(finalCol, 1.0);
}
